# Search recursively for any file with instance_id
from pathlib import Path
import os

def search_for_files(root_dir, pattern, max_depth=3):
    for root, dirs, files in os.walk(root_dir):
        if root.replace(root_dir, '').count(os.sep) >= max_depth:
            continue
        for f in files:
            if pattern in f:
                return Path(root) / f
    return None

print("\nLooking for instance files...")
