seed_positions = []
for r in range(num_rows):
    for c in range(num_cols):
        if input_demo_raw[r][c] == 4:  # In demo, seeds are 4, not 8
            seed_positions.append((r, c))

print(f"Grid size: {num_rows} x {num_cols}")
print(f"Seed positions (4s in input): {seed_positions}")
print(f"Cells that became 4 (were 0): {len(became_4)}")
print(f"Sample of became_4: {became_4[:20]}")

# Stayed 0 - find cells where input is 0 and output is still 0
